Q: Calculate the date yesterday in JavaScript A: <pre><code>function getDiffDays(date) {
    return Math.round((new Date().setHours(0, 0, 0, 0) - new Date(date).setHours(0, 0, 0, 0)) / (1000 * 60 * 60 * 24));
}

const diffDays = getDiffDays(date);
if (diffDays === 0) return 'today';
else if (diffDays === 1) return 'yesterday';
</code></pre>

Q: Flickering when real time capture/drawing on QGraphicsView A: <p>I initially thought your problem stemmed from insufficient speed in capturing the screen image or drawing to the window, but it turns out I was wrong. (I'm not sure if this is one of reason, as I don't understand Qt, but it's certainly not the only reason.)</p>
<p>I created a Color Picker using Windows.Graphics.Capture and Direct2D, using <code>DXGI_SWAP_EFFECT_FLIP_DISCARD</code> and caching the screen image to minimize drawing time. Theoretically, this could capture the screen image and update the window image as quickly as possible, but it still encountered jitter.</p>
<p>Basically, this is because when the window moves, the image moves with the window, then updates to the new image, bouncing back to the correct position.</p>
<p>The following is a similar question that explains the cause of the jitter very well:<br />
<a href="https://stackoverflow.com/questions/53000291/how-to-smooth-ugly-jitter-flicker-jumping-when-resizing-windows-especially-drag">How to smooth ugly jitter/flicker/jumping when resizing windows, especially dragging left/top border (Win 7-10; bg, bitblt and DWM)?</a></p>
<p>I tried drawing during <code>WM_MOVING</code>/<code>WM_MOVE</code>, or pre-drawing at the moved position during <code>WM_MOVING</code>, but this still didn't solve the jitter problem. (Either too late, or too early and causing jitter in the opposite direction)</p>
<p>I finally came up with a solution: create a full-screen window that synchronously displays the captured screen image, and then draw on top of it.</p>
<p>This solution has no drawbacks other than causing a one-frame delay across the entire screen. I could even hide the mouse and draw a fake mouse image on my window, thus eliminating the need for hooks to intercept mouse movements before it occur.</p>
<p>My code isn't completely finished yet; I'll update it when it's complete.</p>
<p>Please note that the following code is not yet complete, including aspects such as error handling, multiple monitors, screen resolution changes, high DPI, local image magnification, reducing mouse speed, and rendering beautiful mouse images, dead code remove, etc.</p>
<pre><code>#include &lt;Windows.h&gt;
#include &lt;iostream&gt;
#include &lt;array&gt;
#include &lt;Uxtheme.h&gt;
#include &lt;string&gt;
#include &lt;format&gt;
#include &lt;d2d1_3.h&gt;
#include &lt;d2d1_3helper.h&gt;
#include &lt;dwrite_3.h&gt;
#include &lt;winrt/base.h&gt;
#include &lt;dxgi1_6.h&gt;
#include &lt;d3d11_4.h&gt;
#include &lt;winrt/Windows.Foundation.h&gt;
#include &lt;winrt/Windows.Graphics.Capture.h&gt;
#include &lt;windows.graphics.capture.interop.h&gt;
#include &lt;windows.graphics.directx.direct3d11.interop.h&gt;
#pragma comment(lib, &quot;Imm32.lib&quot;)
#pragma comment(lib, &quot;UxTheme.lib&quot;)
#pragma comment(lib, &quot;d2d1.lib&quot;)
#pragma comment(lib, &quot;dwrite.lib&quot;)
#pragma comment(lib, &quot;windowsapp.lib&quot;)

using namespace winrt;
using namespace winrt::Windows::Graphics::Capture;
using namespace winrt::Windows::Graphics::DirectX;
using namespace winrt::Windows::Graphics::DirectX::Direct3D11;

HINSTANCE g_hinst;
class Window
{
public:
    HWND GetHWND() const noexcept { return m_hwnd; }
    static LPCWSTR ClassName() noexcept { return L&quot;Color Picker&quot;; };
    static HWND Create();
private:
    static LRESULT CALLBACK s_WndProc(HWND hwnd,
        UINT uMsg, WPARAM wParam, LPARAM lParam);
    LRESULT HandleMessage(
        UINT uMsg, WPARAM wParam, LPARAM lParam);
    Window() {}
    ~Window() {}
    HWND WinCreateWindow(DWORD dwExStyle, LPCTSTR pszName,
        DWORD dwStyle, int x, int y, int cx, int cy,
        HWND hwndParent, HMENU hmenu)
    {
        Register();
        return CreateWindowExW(dwExStyle, ClassName(), pszName, dwStyle,
            x, y, cx, cy, hwndParent, hmenu, g_hinst, this);
    }
    void Register();
    HRESULT OnCreate();
    void OnPaint();
    void OnResize(UINT width, UINT height);
    void OnKeyDown(BYTE VK_code, LPARAM flags);

    HWND m_hwnd = NULL;
    RECT m_pos;
    POINT mousePos = {};

    // shared factories (one per process)
    inline static winrt::com_ptr&lt;ID2D1Factory1&gt; s_d2dFactory = nullptr;
    inline static winrt::com_ptr&lt;IDWriteFactory1&gt; s_dwriteFactory = nullptr;
    static HRESULT CreateDeviceIndependentResources();

    winrt::com_ptr&lt;ID3D11Device&gt; m_d3dDevice;
    winrt::com_ptr&lt;ID3D11DeviceContext&gt; m_d3dContext;
    winrt::com_ptr&lt;IDXGIDevice&gt; m_dxgiDevice;

    winrt::com_ptr&lt;IDXGISwapChain1&gt; m_swapChain;
    winrt::com_ptr&lt;ID2D1Device&gt; m_d2dDevice;
    winrt::com_ptr&lt;ID2D1DeviceContext&gt; m_d2dContext;
    winrt::com_ptr&lt;ID2D1Bitmap1&gt; m_targetBitmap;

    // Direct2D / DirectWrite members
    winrt::com_ptr&lt;ID2D1SolidColorBrush&gt; m_brush;
    winrt::com_ptr&lt;IDWriteTextFormat&gt; m_textFormat;

    int m_frameCount = 0;
    HRESULT CreateDeviceResources();
    HRESULT SetD2dContextWithSwapChain();  //Form GetBuffer to SetTarget

    void DiscardDeviceResources();

    HRESULT StartCapture();
    HRESULT HandleDeviceLost();
    void OnFrameArrived(winrt::Windows::Graphics::Capture::Direct3D11CaptureFramePool, winrt::Windows::Foundation::IInspectable);

    winrt::Windows::Graphics::Capture::Direct3D11CaptureFramePool m_framePool = nullptr;
    GraphicsCaptureSession m_session = nullptr;
    Direct3D11CaptureFrame m_lastFrame = nullptr;

    winrt::com_ptr&lt;ID2D1Bitmap1&gt; m_frameBitmap;

    winrt::com_ptr&lt;ID3D11Texture2D&gt; m_stagingTexture;
    std::vector&lt;BYTE&gt; m_frameData;
    D3D11_MAPPED_SUBRESOURCE m_mapped{};
};
HWND Window::Create()
{
    POINT mouse; GetCursorPos(&amp;mouse);
    HMONITOR hDisplay= MonitorFromPoint(mouse, MONITOR_DEFAULTTONEAREST);
    MONITORINFO displayInfo{ sizeof(displayInfo) };
    GetMonitorInfoW(hDisplay, &amp;displayInfo);

    Window* self = new Window();
    if (HWND hwnd = self-&gt;WinCreateWindow(WS_EX_NOREDIRECTIONBITMAP,
        L&quot;Color Picker&quot;, WS_POPUP,
        displayInfo.rcMonitor.left, displayInfo.rcMonitor.top, 
        (displayInfo.rcMonitor.right - displayInfo.rcMonitor.left),
        displayInfo.rcMonitor.bottom - displayInfo.rcMonitor.top,
        NULL, NULL)) {
        return hwnd;
    }
    delete self;
    return NULL;
}
void Window::Register()
{
    WNDCLASSW wc{};
    wc.style = 0;
    wc.lpfnWndProc = Window::s_WndProc;
    wc.cbClsExtra = 0;
    wc.cbWndExtra = 0;
    wc.hInstance = g_hinst;
    wc.hIcon = NULL;
    wc.hCursor = NULL;
    wc.hbrBackground = NULL;
    wc.lpszMenuName = NULL;
    wc.lpszClassName = ClassName();
    RegisterClassW(&amp;wc);
}
LRESULT CALLBACK Window::s_WndProc(
    HWND hwnd, UINT uMsg, WPARAM wParam, LPARAM lParam)
{
    Window* self;
    if (uMsg == WM_NCCREATE) {
        LPCREATESTRUCT lpcs = reinterpret_cast&lt;LPCREATESTRUCT&gt;(lParam);
        self = reinterpret_cast&lt;Window*&gt;(lpcs-&gt;lpCreateParams);
        self-&gt;m_hwnd = hwnd;
        SetWindowLongPtrW(hwnd, GWLP_USERDATA,
            reinterpret_cast&lt;LPARAM&gt;(self));
    }
    else {
        self = reinterpret_cast&lt;Window*&gt;
            (GetWindowLongPtrW(hwnd, GWLP_USERDATA));
    }
    if (self) {
        return self-&gt;HandleMessage(uMsg, wParam, lParam);
    }
    else {
        return DefWindowProcW(hwnd, uMsg, wParam, lParam);
    }
}
LRESULT Window::HandleMessage(
    UINT uMsg, WPARAM wParam, LPARAM lParam)
{
    switch (uMsg) {
    case WM_NCDESTROY: {
        LRESULT lres = DefWindowProcW(m_hwnd, uMsg, wParam, lParam);
        SetWindowLongPtrW(m_hwnd, GWLP_USERDATA, 0);
        DiscardDeviceResources();
        delete this;
        PostQuitMessage(0);
        return lres;
    }
    case WM_CREATE:
        OnCreate();
        return 0;
    case WM_PAINT:
        OnPaint();
        return 0;
    case WM_KEYDOWN:
        OnKeyDown(static_cast&lt;BYTE&gt;(wParam), lParam);
        return 0;
    case WM_MOUSEMOVE:
        InvalidateRect(m_hwnd, nullptr, FALSE);
        return 0;
    case WM_SIZE:
        OnResize(LOWORD(lParam), HIWORD(lParam));
        return 0;
    case WM_SETCURSOR:
        SetCursor(NULL);
        return TRUE;
    }

    return DefWindowProcW(m_hwnd, uMsg, wParam, lParam);
}
HRESULT Window::OnCreate() {
    SetWindowDisplayAffinity(m_hwnd, WDA_EXCLUDEFROMCAPTURE);
    CreateDeviceIndependentResources();
    CreateDeviceResources();
    return StartCapture();
}
void Window::OnPaint()
{
    InvalidateRect(m_hwnd, nullptr, FALSE);
    HRESULT hr = CreateDeviceResources();
    if (SUCCEEDED(hr) &amp;&amp; m_d2dContext) {

        m_d2dContext-&gt;BeginDraw();

        if (m_frameBitmap) {
            m_d2dContext-&gt;DrawBitmap(
                m_frameBitmap.get(),
                nullptr,
                1.0f,
                D2D1_BITMAP_INTERPOLATION_MODE_NEAREST_NEIGHBOR,
                nullptr);
        }

        if (m_stagingTexture) {
            if (!m_mapped.pData) {
                hr = m_d3dContext-&gt;Map(m_stagingTexture.get(), 0, D3D11_MAP_READ, 0, &amp;m_mapped);
                if (FAILED(hr)) {
                    HandleDeviceLost();
                    return;
                }
                m_frameData.resize(m_mapped.DepthPitch);
                memcpy(m_frameData.data(), m_mapped.pData, m_mapped.DepthPitch);
            }
            if (m_mapped.pData) {
                POINT pos;
                GetCursorPos(&amp;pos);
                const BYTE* pdata = m_frameData.data();
                if (pos.y * m_mapped.RowPitch + pos.x * 4 + 3 &lt; m_frameData.size()) {
                    int r = pdata[2 + pos.y * m_mapped.RowPitch + pos.x * 4];
                    int g = pdata[1 + pos.y * m_mapped.RowPitch + pos.x * 4];
                    int b = pdata[0 + pos.y * m_mapped.RowPitch + pos.x * 4];

                    m_brush-&gt;SetColor(D2D1::ColorF(r / 255.0, g / 255.0, b / 255.0));
                    GetCursorPos(&amp;mousePos);
                    m_d2dContext-&gt;DrawRectangle(
                        D2D1_RECT_F{ float(mousePos.x - 64),float(mousePos.y - 64),float(mousePos.x + 64),float(mousePos.y + 64) },
                        m_brush.get(), 10
                    );
                    auto str = std::format(L&quot;R:{}\nG:{}\nB:{}&quot;, r, g, b);
                    m_d2dContext-&gt;DrawTextW(str.c_str(), str.length(), m_textFormat.get(), { 5,50,300,300 }, m_brush.get());
                }
            }
        }

        auto str = std::format(L&quot;{}&quot;, m_frameCount);
        m_brush-&gt;SetColor(D2D1::ColorF(1, 1, 1));
        m_d2dContext-&gt;DrawTextW(str.c_str(), str.length(), m_textFormat.get(), { 5,0,300,300 }, m_brush.get());

        RECT client;
        GetClientRect(m_hwnd, &amp;client);
        m_brush-&gt;SetColor(D2D1::ColorF(1, 0, 0,0.05));
        m_d2dContext-&gt;FillRectangle(D2D1::RectF(0, 0, client.right, client.bottom), m_brush.get());
        m_d2dContext-&gt;EndDraw();

        hr = m_swapChain-&gt;Present(1, 0);
        if (FAILED(hr)) {
            // device lost
            HandleDeviceLost();
            return;
        }
    }
    ValidateRect(m_hwnd, nullptr);
}
HRESULT Window::CreateDeviceIndependentResources() {
    if (!s_d2dFactory) {
        D2D1CreateFactory(D2D1_FACTORY_TYPE_SINGLE_THREADED, s_d2dFactory.put());
    }
    if (!s_dwriteFactory) {
        DWriteCreateFactory(DWRITE_FACTORY_TYPE_SHARED, __uuidof(IDWriteFactory), reinterpret_cast&lt;IUnknown**&gt;(s_dwriteFactory.put()));
    }
    return S_OK;
}
HRESULT Window::CreateDeviceResources() {
    if (m_d2dContext) {
        return S_OK;
    }
    if (!s_d2dFactory)
        return E_FAIL;
    HRESULT hr;
    hr = D3D11CreateDevice(nullptr,
        D3D_DRIVER_TYPE_HARDWARE,
        nullptr,
        D3D11_CREATE_DEVICE_BGRA_SUPPORT
#ifdef _DEBUG
        | D3D11_CREATE_DEVICE_DEBUG
#endif // _DEBUG
        , nullptr, 0,
        D3D11_SDK_VERSION,
        m_d3dDevice.put(),
        nullptr,
        m_d3dContext.put());
    if (FAILED(hr)) {return hr; }

    m_d3dDevice.as(m_dxgiDevice);

    winrt::com_ptr&lt;IDXGIAdapter&gt; adapter;
    hr = m_dxgiDevice-&gt;GetAdapter(adapter.put());
    if (FAILED(hr)) { return hr; }

    winrt::com_ptr&lt;IDXGIFactory2&gt; factory;
    hr=adapter-&gt;GetParent(__uuidof(IDXGIFactory2), factory.put_void());
    if (FAILED(hr)) { return hr; }

    hr=factory-&gt;MakeWindowAssociation(m_hwnd, DXGI_MWA_NO_ALT_ENTER);
    assert(SUCCEEDED(hr));

    DXGI_SWAP_CHAIN_DESC1 desc{};
    desc.Width = 0;
    desc.Height = 0;
    desc.Format = DXGI_FORMAT_B8G8R8A8_UNORM;
    desc.Stereo = false;
    desc.SampleDesc.Count = 1; //no MSAA
    desc.BufferUsage = DXGI_USAGE_RENDER_TARGET_OUTPUT;
    desc.BufferCount = 2;
    desc.Scaling = DXGI_SCALING_NONE;
    desc.SwapEffect = DXGI_SWAP_EFFECT_FLIP_DISCARD;
    desc.AlphaMode = DXGI_ALPHA_MODE_UNSPECIFIED;

    hr = factory-&gt;CreateSwapChainForHwnd(
        m_d3dDevice.get(),
        m_hwnd,
        &amp;desc,
        nullptr,
        nullptr,
        m_swapChain.put()
    );
    if (FAILED(hr)) { return hr; }

    hr=s_d2dFactory-&gt;CreateDevice(
        m_dxgiDevice.get(),
        m_d2dDevice.put()
    );
    if (FAILED(hr)) { return hr; }
    hr=m_d2dDevice-&gt;CreateDeviceContext(
        D2D1_DEVICE_CONTEXT_OPTIONS_NONE,
        m_d2dContext.put()
    );
    if (FAILED(hr)) { return hr; }

    hr=SetD2dContextWithSwapChain();
    if (FAILED(hr)) { return hr; }

    if (!m_textFormat) {
        // create text format (Segoe UI, 18pt)
        if (s_dwriteFactory) {
            hr= s_dwriteFactory-&gt;CreateTextFormat(
                L&quot;Segoe UI&quot;, nullptr, DWRITE_FONT_WEIGHT_NORMAL,
                DWRITE_FONT_STYLE_NORMAL, DWRITE_FONT_STRETCH_NORMAL,
                18, L&quot;en-us&quot;, m_textFormat.put()
            );
            if (FAILED(hr)) { return hr; }
            if (m_textFormat) {
                m_textFormat-&gt;SetTextAlignment(DWRITE_TEXT_ALIGNMENT_LEADING);
                m_textFormat-&gt;SetParagraphAlignment(DWRITE_PARAGRAPH_ALIGNMENT_NEAR);
            }
        }
    }

    hr = m_d2dContext-&gt;CreateSolidColorBrush(D2D1::ColorF(1, 1, 1), m_brush.put());
    return hr;
}
HRESULT Window::SetD2dContextWithSwapChain() {
    winrt::com_ptr&lt;IDXGISurface&gt; dxgiBackBuffer;
    HRESULT hr;
    hr = m_swapChain-&gt;GetBuffer(
        0,
        __uuidof(IDXGISurface),
        dxgiBackBuffer.put_void()
    );
    if (FAILED(hr)) { return hr; }

    D2D1_BITMAP_PROPERTIES1 props =
        D2D1::BitmapProperties1(
            D2D1_BITMAP_OPTIONS_TARGET |
            D2D1_BITMAP_OPTIONS_CANNOT_DRAW,
            D2D1::PixelFormat(
                DXGI_FORMAT_B8G8R8A8_UNORM,
                D2D1_ALPHA_MODE_IGNORE
            )
        );

    hr = m_d2dContext-&gt;CreateBitmapFromDxgiSurface(
        dxgiBackBuffer.get(),
        &amp;props,
        m_targetBitmap.put()
    );

    m_d2dContext-&gt;SetTarget(m_targetBitmap.get());
    return hr;
}
void Window::DiscardDeviceResources() {
    if (m_mapped.pData) {
        m_d3dContext-&gt;Unmap(m_stagingTexture.get(), 0);
        m_mapped.pData = nullptr;
    }
    m_stagingTexture = nullptr;

    m_frameBitmap = nullptr;
    m_lastFrame = nullptr;
    if (m_session) {
        m_session.Close(); m_session = nullptr;
    }
    if (m_framePool) {
        m_framePool.Close(); m_framePool = nullptr;
    }

    m_textFormat = nullptr;
    m_brush = nullptr;

    m_targetBitmap = nullptr;
    m_d2dContext = nullptr;
    m_d2dDevice = nullptr;
    m_swapChain = nullptr;

    m_dxgiDevice = nullptr;
    if (m_d3dContext) {
        m_d3dContext-&gt;ClearState();
        m_d3dContext-&gt;Flush();
        m_d3dContext = nullptr;
    }
    m_d3dDevice = nullptr;
    return;
}
HRESULT Window::HandleDeviceLost() {
    int i = 0;
retry:
    DiscardDeviceResources();
    CreateDeviceResources();
    HRESULT hr = StartCapture();
    if (hr == DXGI_ERROR_DEVICE_REMOVED) {
        ++i;
        assert(i &lt; 10);

        Sleep(100);
        goto retry;
    }
    return hr;
}
HRESULT Window::StartCapture() {
    HMONITOR captureTarget = MonitorFromWindow(m_hwnd, MONITOR_DEFAULTTONEAREST);

    winrt::com_ptr&lt;IInspectable&gt; inspectable;
    HRESULT hr = CreateDirect3D11DeviceFromDXGIDevice(m_dxgiDevice.get(), inspectable.put());
    if (FAILED(hr)) { return hr; }
    IDirect3DDevice device = inspectable.as&lt;IDirect3DDevice&gt;();

    MONITORINFO monitorInfo;
    monitorInfo.cbSize = sizeof(monitorInfo);
    GetMonitorInfoW(captureTarget, &amp;monitorInfo);
    winrt::Windows::Graphics::SizeInt32 frameSize{ monitorInfo.rcMonitor.right - monitorInfo.rcMonitor.left, monitorInfo.rcMonitor.bottom - monitorInfo.rcMonitor.top };

    auto interopFactory = get_activation_factory&lt;GraphicsCaptureItem&gt;().as&lt;IGraphicsCaptureItemInterop&gt;();
    GraphicsCaptureItem item = nullptr;
    hr = interopFactory-&gt;CreateForMonitor(
        captureTarget,
        __uuidof(ABI::Windows::Graphics::Capture::IGraphicsCaptureItem),
        put_abi(item));
    if (FAILED(hr)) { return hr; }

    m_framePool = Direct3D11CaptureFramePool::Create(
        device,
        DirectXPixelFormat::B8G8R8A8UIntNormalized,
        2,
        frameSize);

    m_session = m_framePool.CreateCaptureSession(item);
    m_session.IsCursorCaptureEnabled(false);
    //session.IsBorderRequired(false);
    m_session.MinUpdateInterval(std::chrono::milliseconds(1));

    m_framePool.FrameArrived({ this, &amp;Window::OnFrameArrived });

    m_session.StartCapture();
    return hr;
}
void Window::OnFrameArrived(winrt::Windows::Graphics::Capture::Direct3D11CaptureFramePool framePool, winrt::Windows::Foundation::IInspectable) {
    auto newFrame = framePool.TryGetNextFrame();
    if (!newFrame) {
        return;
    }
    auto surface = newFrame.Surface();

    auto access = surface.as&lt;::Windows::Graphics::DirectX::Direct3D11::IDirect3DDxgiInterfaceAccess&gt;();
    winrt::com_ptr&lt;ID3D11Texture2D&gt; texture;

    HRESULT hr = access-&gt;GetInterface(__uuidof(ID3D11Texture2D), texture.put_void());
    if (FAILED(hr)) { return; }

    if (m_mapped.pData) {
        m_d3dContext-&gt;Unmap(m_stagingTexture.get(), 0);
        m_mapped.pData = nullptr;
    }
    else if (!m_stagingTexture) {
        D3D11_TEXTURE2D_DESC desc{};
        texture-&gt;GetDesc(&amp;desc);
        desc.Usage = D3D11_USAGE_STAGING;
        desc.BindFlags = 0;
        desc.CPUAccessFlags = D3D11_CPU_ACCESS_READ;
        desc.MiscFlags = 0;
        hr = m_d3dDevice-&gt;CreateTexture2D(&amp;desc, nullptr, m_stagingTexture.put());
        if (FAILED(hr)) { return; }
    }

    m_d3dContext-&gt;CopyResource(m_stagingTexture.get(), texture.get());
    m_lastFrame = std::move(newFrame);
    m_d3dContext-&gt;Flush();

    m_frameBitmap = nullptr;
    winrt::com_ptr&lt;IDXGISurface&gt; dxgiSurface;
    texture.as(dxgiSurface);
    D2D1_BITMAP_PROPERTIES1 props =
        D2D1::BitmapProperties1(
            D2D1_BITMAP_OPTIONS_NONE,
            D2D1::PixelFormat(
                DXGI_FORMAT_B8G8R8A8_UNORM,
                D2D1_ALPHA_MODE_IGNORE
            )
        );

    hr = m_d2dContext-&gt;CreateBitmapFromDxgiSurface(dxgiSurface.get(), props, m_frameBitmap.put());
    m_frameCount++;
    InvalidateRect(m_hwnd, nullptr, FALSE);
    return;
}
void Window::OnResize(UINT width, UINT height) {
    m_d2dContext-&gt;SetTarget(nullptr);
    m_targetBitmap = nullptr;
    HRESULT hr = m_swapChain-&gt;ResizeBuffers(0, 0, 0, DXGI_FORMAT_UNKNOWN, NULL);
    hr = SetD2dContextWithSwapChain();
    InvalidateRect(m_hwnd, nullptr, false);

    return;
}
void Window::OnKeyDown(BYTE VK_code,LPARAM flags) {}
int //WINAPI
//wWinMain(HINSTANCE hinst, HINSTANCE, LPWSTR pCmdLine, int nShowCmd)
main()
{
    //g_hinst = hinst;
    g_hinst = GetModuleHandleW(NULL);
    SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE);
    winrt::init_apartment(winrt::apartment_type::multi_threaded);

    HWND hwnd = Window::Create();
    if (!hwnd) {
        MessageBoxW(NULL, L&quot;Create window failed!&quot;, GetCommandLineW(), MB_OK);
        return 0;
    }
    ImmDisableIME(0);
    ShowWindow(hwnd, SW_SHOW);
    SetForegroundWindow(hwnd);
    MSG msg;
    while (GetMessageW(&amp;msg, NULL, 0, 0)) {
        DispatchMessageW(&amp;msg);
    }
    return 0;
}
